using System.Diagnostics;
using System.Numerics;
using UltimateArena.Core;
using UltimateArena.Graphics;
using UltimateArena.Native;
using UltimateArena.Network;
namespace UltimateArena;
internal sealed class DesktopGame:IDisposable {
    private readonly DesktopWindow window=new();private readonly Renderer renderer=new();private readonly AudioMixer audio=new();private readonly Settings settings=Settings.Load();private readonly bool[] down=new bool[256],previous=new bool[256];private readonly List<(string Text,float At)> feed=[];private readonly Stopwatch clock=Stopwatch.StartNew();
    private World world=new(1701,5);private MatchHost? host;private MatchClient? client;private Fighter? player;private int localId,weapon,focus;private float yaw,pitch,kick,hit,hurt,lastHealth=100,now;private uint eventSeen;private bool menu=true,hasMatch,connecting;private string status="NATIVE C# / OPENGL / ALL ORIGINAL ASSETS";private int fps,frameCount;private double fpsAt;
    public DesktopGame(){window.SetVsync(settings.Vsync);audio.Volume=settings.Volume;}
    private bool Pressed(int key)=>down[key]&&!previous[key];
    private bool Button(float x,float y,float width,float height,string title,string sub,bool primary=false){bool hover=window.MouseX*1600f/window.Width>=x&&window.MouseX*1600f/window.Width<=x+width&&window.MouseY*900f/window.Height>=y&&window.MouseY*900f/window.Height<=y+height;var c=primary?Canvas.Cyan:Canvas.Dark;Canvas.Rect(x,y,width,height,hover?Vector3.Lerp(c,Vector3.One,.12f):c,.95f);Canvas.Border(x,y,width,height,primary?Canvas.Cyan:new(.22f,.4f,.44f));Canvas.Text(title,x+18,y+17,2,primary?Canvas.Dark:Canvas.White);if(sub.Length>0)Canvas.Text(sub,x+18,y+43,1.1f,primary?new(.13f,.3f,.32f):Canvas.Muted);return hover&&Pressed(1);}
    private void ResetConnection(){client?.Dispose();client=null;host?.Dispose();host=null;connecting=false;}
    private void Solo(){ResetConnection();world=new(1701,settings.Bots);player=world.Add(settings.Name);localId=player.Id;yaw=player.Yaw;pitch=0;weapon=0;lastHealth=100;eventSeen=0;feed.Clear();hasMatch=true;menu=false;window.Capture(true);settings.Save();}
    private void Join(bool hosting){try{ResetConnection();if(hosting){host=new(27960,settings.Bots);host.Start();settings.Address="127.0.0.1:27960";}client=new(settings.Address,settings.Name);connecting=true;status=hosting?"HOST STARTED - CONNECTING...":"CONNECTING TO "+settings.Address;settings.Save();}catch(Exception ex)when(ex is System.Net.Sockets.SocketException or FormatException or ArgumentException){status="CONNECTION ERROR: "+ex.Message.ToUpperInvariant();}}
    private void Resume(){if(!hasMatch)return;menu=false;focus=0;window.Capture(true);}
    private void OpenMenu(){menu=true;focus=0;window.Capture(false);}
    private InputState Input()=>new(){Forward=menu?0:(down[0x57]?1:0)-(down[0x53]?1:0),Side=menu?0:(down[0x44]?1:0)-(down[0x41]?1:0),Yaw=yaw,Pitch=pitch,Weapon=weapon,Jump=!menu&&down[32],Dodge=!menu&&down[16],Crouch=!menu&&down[17],Fire=!menu&&down[1],Alt=!menu&&down[2]};
    public void Run(){double last=clock.Elapsed.TotalSeconds,acc=0;while(window.Running){double tick=clock.Elapsed.TotalSeconds;float dt=(float)Math.Min(.1,tick-last);last=tick;now=(float)tick;window.Poll();for(int k=0;k<256;k++){previous[k]=down[k];down[k]=window.Key(k);}if(!window.Active&&!menu)OpenMenu();
            if(Pressed(27)){if(focus!=0)focus=0;else if(menu&&hasMatch)Resume();else if(!menu)OpenMenu();}
            if(!menu){if(Pressed(0x46)||Pressed(0x7A)){window.ToggleFullscreen();window.Capture(true);}yaw=MathEx.Angle(yaw+window.DeltaX*.0022f*settings.Sensitivity);pitch=Math.Clamp(pitch-window.DeltaY*.0022f*settings.Sensitivity,-1.4f,1.4f);for(int i=0;i<6;i++)if(Pressed(0x31+i))weapon=i;if(window.Wheel!=0)weapon=(weapon-Math.Sign(window.Wheel)+6)%6;}
            if(client!=null){client.Pump();if(client.Connected&&client.Predicted!=null){if(connecting){connecting=false;eventSeen=0;lastHealth=100;feed.Clear();localId=client.Id;weapon=client.Predicted.Weapon;yaw=client.Predicted.Yaw;pitch=client.Predicted.Pitch;hasMatch=true;menu=false;window.Capture(true);}world=client.World;player=client.Predicted;}if(connecting)status=client.Status;if(hasMatch&&!client.Connected&&!connecting){status=client.Status;OpenMenu();}foreach(var e in client.Received)Event(e);client.Received.Clear();}
            acc+=dt;while(acc>=World.Tick){var input=Input();if(client!=null){client.Input(input);}else if(hasMatch){if(player!=null)player.Input=input;if(!menu)world.Step();}else world.Step();acc-=World.Tick;}
            if(client==null&&hasMatch)player=world.Fighters.Find(p=>p.Id==localId);if(client==null)foreach(var e in world.Events)if(e.Id>eventSeen)Event(e);
            if(player!=null){if(player.Health<lastHealth)hurt=.65f;if(lastHealth<=0&&player.Health>0){yaw=player.Yaw;pitch=player.Pitch;}lastHealth=player.Health;}
            kick=MathF.Max(0,kick-dt*7);hit=MathF.Max(0,hit-dt*8);hurt=MathF.Max(0,hurt-dt);Vector3 eye;float viewYaw,viewPitch;if(hasMatch&&player!=null){eye=player.Position+new Vector3(0,player.Health>0?1.45f:.5f,0);viewYaw=yaw;viewPitch=pitch;}else{float angle=now*.035f;eye=new(19*MathF.Cos(angle),10,19*MathF.Sin(angle));viewYaw=MathF.Atan2(-eye.X,eye.Z);viewPitch=-.33f;}
            renderer.Draw(world,eye,viewYaw,viewPitch,hasMatch?localId:0,window.Width,window.Height,now,hasMatch&&player?.Health>0,weapon,kick,!menu&&weapon==3&&down[2]);Canvas.Begin();if(hasMatch&&player!=null)Hud(player);if(menu)Menu();Canvas.End();window.Swap();frameCount++;if(tick-fpsAt>=1){fps=frameCount;frameCount=0;fpsAt=tick;}if(!settings.Vsync)Thread.Sleep(1);
        }}
    private void Event(GameEvent e){eventSeen=Math.Max(eventSeen,e.Id);renderer.Effect(e,now);if(!hasMatch)return;bool own=e.Owner==localId;var p=player;float gain=own?.17f:.045f;if(!own&&p!=null)gain/=1+Vector3.Distance(p.Position,e.A)*.06f;
        if(e.Kind==EventKind.Shot){float[] freq=[700,220,100,1100,90,160],duration=[.12f,.07f,.2f,.28f,.3f,.2f];audio.Play(freq[e.Weapon],duration[e.Weapon],gain,e.Weapon!=3);if(own)kick=1;}
        if(e.Kind==EventKind.Explosion)audio.Play(70,.45f,.22f);
        if(e.Kind==EventKind.Hit&&own){hit=1;audio.Play(1100,.06f,.1f,false);}
        if(e.Kind==EventKind.Pickup&&own)audio.Play(800,.16f,.1f,false);
        if(e.Kind==EventKind.Kill){string a=world.Fighters.Find(p=>p.Id==e.Owner)?.Name??"LEFT",b=world.Fighters.Find(p=>p.Id==e.Target)?.Name??"LEFT";feed.Insert(0,($"{a}  / {Weapons.All[e.Weapon].Name} /  {b}",now));if(feed.Count>5)feed.RemoveAt(5);}
    }
    private void Hud(Fighter p){Canvas.Rect(0,0,1600,90,Canvas.Dark,.8f);Canvas.Text("UA",32,24,5,Canvas.Cyan);Canvas.Text("ULTIMATE ARENA",125,25,1.5f);Canvas.Text("THE FOUNDRY / DEATHMATCH",125,47,1.2f,Canvas.Muted);Canvas.Text($"{Math.Max(0,(int)world.RoundTime)/60:00}:{Math.Max(0,(int)world.RoundTime)%60:00}",1310,26,3);Canvas.Text(client==null?"LOCAL / 60 HZ":$"{(host==null?"CLIENT":"HOST")} / {client.Ping} MS",1280,62,1.2f,Canvas.Cyan);
        Canvas.Rect(0,790,1600,110,Canvas.Dark,.92f);Canvas.Text("VITALS",30,808,1.2f,Canvas.Muted);Canvas.Text(MathF.Ceiling(p.Health).ToString(),30,833,5,Canvas.Cyan);Canvas.Text(MathF.Ceiling(p.Armor).ToString(),155,833,5,Canvas.Amber);Canvas.Rect(30,881,100,4,Canvas.Cyan,.2f);Canvas.Rect(30,881,p.Health,4,Canvas.Cyan);Canvas.Rect(155,881,p.Armor,4,Canvas.Amber);
        for(int i=0;i<6;i++){float x=345+i*137;bool chosen=weapon==i;Canvas.Rect(x,817,127,67,chosen?new(.09f,.24f,.28f):Canvas.Dark,.9f);Canvas.Rect(x,817,127,2,chosen?Canvas.Cyan:Canvas.Muted);Canvas.Text($"0{i+1}",x+10,828,1.2f,Canvas.Muted);Canvas.Text(Weapons.All[i].Name,x+10,848,1.6f,chosen?Canvas.White:Canvas.Muted);Canvas.Text(p.Ammo[i].ToString(),x+10,870,1,Canvas.Muted);}
        Canvas.Text(Weapons.All[weapon].Role,1225,795,1.1f,Canvas.Muted);Canvas.Text(p.Ammo[weapon].ToString(),1415,818,6);Canvas.Text("RMB / "+Weapons.All[weapon].Alternate,1225,881,1,Canvas.Amber);Canvas.Text($"{MathEx.Horizontal(p.Velocity):0.0} M/S   {fps} FPS",32,755,1.2f,Canvas.Muted);
        Canvas.Rect(799,435,2,7,Canvas.White,.8f);Canvas.Rect(799,458,2,7,Canvas.White,.8f);Canvas.Rect(785,449,7,2,Canvas.White,.8f);Canvas.Rect(808,449,7,2,Canvas.White,.8f);if(hit>0){Canvas.Text("X",788,438,4,Canvas.Amber,hit);}if(hurt>0){Canvas.Border(1,1,1597,897,new(1,.2f,.1f),hurt);Canvas.Rect(0,0,1600,900,new(.7f,.1f,.03f),hurt*.15f);}
        feed.RemoveAll(f=>now-f.At>5);for(int i=0;i<feed.Count;i++){string t=feed[i].Text;float width=Canvas.Width(t,1.3f);Canvas.Rect(1570-width-20,110+i*31,width+20,25,Canvas.Dark,.85f);Canvas.Text(t,1570-width-10,118+i*31,1.3f,Canvas.Amber);}
        if(p.Health<=0)Canvas.Center($"ELIMINATED / RESPAWN IN {MathF.Ceiling(p.Respawn)}",400,3,Canvas.Amber);if(world.Winner.Length>0){Canvas.Center(world.Winner+" WINS",320,5,Canvas.Amber);Canvas.Center($"NEXT ROUND IN {MathF.Ceiling(world.Restart)}",380,2);}
        if(down[9]&&!menu){Canvas.Rect(440,180,720,500,Canvas.Dark,.97f);Canvas.Border(440,180,720,500,Canvas.Cyan);Canvas.Text("THE FOUNDRY / SCOREBOARD",470,210,2.5f);Canvas.Text("FRAGS   DEATHS",900,260,1.5f,Canvas.Muted);int row=0;foreach(var q in world.Fighters.OrderByDescending(p=>p.Score)){if(row>10)break;float y=300+row++*31;Canvas.Text(q.Name+(q.Bot?" / BOT":""),470,y,1.8f,q.Id==localId?Canvas.Cyan:Canvas.White);Canvas.Text($"{q.Score,3}      {q.Deaths,3}",920,y,1.8f);}}
    }
    private void Menu(){Canvas.Rect(0,0,940,900,Canvas.Dark,.95f);Canvas.Rect(940,0,660,900,Canvas.Dark,.22f);Canvas.Text("NATIVE DESKTOP / C#",65,32,1.4f,Canvas.Cyan);Canvas.Text("PROTOTYPE 0.2",1340,32,1.3f,Canvas.Muted);Canvas.Rect(65,66,1470,1,Canvas.Muted,.5f);Canvas.Text("ORBITAL RECLAMATION FACILITY",65,103,1.6f,Canvas.Cyan);Canvas.Text("ULTIMATE",65,150,10);Canvas.Text("ARENA",65,238,10,Canvas.Amber);Canvas.Text("THE FOUNDRY / SECTOR 01",70,335,2,Canvas.Muted);Canvas.Text("SIX WEAPONS. TWO GALLERIES. NO SAFE CORNER.",70,385,1.6f);
        bool solo=Button(65,425,310,78,"ENTER THE ARENA","1 / SOLO + "+settings.Bots+" BOTS",true),hosting=Button(395,425,230,78,"HOST MATCH","2 / UDP :27960"),join=Button(645,425,230,78,"JOIN MATCH","3 / ENTER ADDRESS");
        Field(65,535,310,"CALLSIGN",settings.Name,1);Field(395,535,480,"HOST ADDRESS",settings.Address,2);
        Canvas.Text("SENSITIVITY",65,620,1.2f,Canvas.Muted);Canvas.Text(settings.Sensitivity.ToString("0.0"),65,649,2);if(Button(145,635,45,38,"-",""))settings.Sensitivity=MathF.Max(.2f,settings.Sensitivity-.1f);if(Button(200,635,45,38,"+",""))settings.Sensitivity=MathF.Min(3,settings.Sensitivity+.1f);
        Canvas.Text("VOLUME",285,620,1.2f,Canvas.Muted);Canvas.Text($"{settings.Volume*100:0}%",285,649,2);if(Button(375,635,45,38,"-",""))settings.Volume=MathF.Max(0,settings.Volume-.05f);if(Button(430,635,45,38,"+",""))settings.Volume=MathF.Min(1,settings.Volume+.05f);audio.Volume=settings.Volume;
        Canvas.Text("BOTS",520,620,1.2f,Canvas.Muted);Canvas.Text(settings.Bots.ToString(),520,649,2);if(Button(570,635,45,38,"-",""))settings.Bots=Math.Max(0,settings.Bots-1);if(Button(625,635,45,38,"+",""))settings.Bots=Math.Min(10,settings.Bots+1);
        if(Button(715,635,160,38,settings.Vsync?"VSYNC ON":"VSYNC OFF","")){settings.Vsync=!settings.Vsync;window.SetVsync(settings.Vsync);}
        Canvas.Text("WASD MOVE / SPACE JUMP / SHIFT DODGE / CTRL STEADY",65,710,1.3f,Canvas.Muted);Canvas.Text("1-6 OR WHEEL WEAPON / LMB FIRE / RMB ALT / TAB SCORES",65,737,1.3f,Canvas.Muted);Canvas.Text("ESC MENU / F OR F11 FULLSCREEN",65,764,1.3f,Canvas.Muted);Canvas.Text(status.Length>95?status[..95]:status,65,805,1.1f,Canvas.Cyan);
        if(hasMatch&&Button(1050,690,390,70,"RESUME MATCH","ESC / BACK TO THE ARENA"))Resume();if(Button(1050,780,390,60,"EXIT GAME",""))window.Running=false;
        Canvas.Text("HOT METAL.",1050,420,5,Canvas.Amber);Canvas.Text("COLD VACUUM.",1050,470,5);Canvas.Text("48 X 48 METRES / FIRST TO 20",1050,545,1.5f,Canvas.Muted);Canvas.Text("ORIGINAL PROCEDURAL MATERIALS",1050,577,1.3f,Canvas.Muted);Canvas.Rect(65,855,1470,1,Canvas.Muted,.5f);Canvas.Text("OPENGL / NATIVE INPUT / UDP MATCH HOST",65,875,1.1f,Canvas.Muted);Canvas.Text(audio.Available?"AUDIO READY":"NO AUDIO DEVICE",1320,875,1.1f,Canvas.Muted);
        if(focus!=0){foreach(char c in window.Characters){if(focus==1&&settings.Name.Length<16&&(char.IsAsciiLetterOrDigit(c)||c is ' ' or '_' or '-'))settings.Name+=char.ToUpperInvariant(c);if(focus==2&&settings.Address.Length<64&&(char.IsAsciiLetterOrDigit(c)||c is '.' or ':' or '-'))settings.Address+=c;}if(Pressed(8)){if(focus==1&&settings.Name.Length>0)settings.Name=settings.Name[..^1];if(focus==2&&settings.Address.Length>0)settings.Address=settings.Address[..^1];}if(Pressed(13)){if(focus==2)join=true;focus=0;}}else{solo|=Pressed(0x31);hosting|=Pressed(0x32);join|=Pressed(0x33);}
        if(solo)Solo();else if(hosting)Join(true);else if(join)Join(false);
    }
    private void Field(float x,float y,float width,string label,string value,int id){Canvas.Text(label,x,y,1.1f,Canvas.Muted);Canvas.Rect(x,y+21,width,42,new(.06f,.13f,.17f));Canvas.Border(x,y+21,width,42,focus==id?Canvas.Cyan:new(.2f,.35f,.4f));Canvas.Text(value+(focus==id&&((int)(now*2)%2==0)?"_":""),x+12,y+35,1.6f);float mx=window.MouseX*1600f/window.Width,my=window.MouseY*900f/window.Height;if(Pressed(1)&&mx>=x&&mx<=x+width&&my>=y+21&&my<=y+63)focus=id;}
    public void Dispose(){settings.Save();ResetConnection();audio.Dispose();window.Dispose();}
}
